// Simple Starfield Run game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// Ship
const ship = {x: canvas.width/2, y: canvas.height-60, w:30, h:30, speed:4, health:3};
let keys = {};
addEventListener('keydown',e=>keys[e.key]=true);
addEventListener('keyup',e=>keys[e.key]=false);

// Entities
let asteroids = [];
let orbs = [];
let score = 0;
let lastAst = 0, lastOrb = 0;

function spawnAsteroid(){
  const size = 20+Math.random()*30;
  asteroids.push({x:Math.random()* (canvas.width-size), y:-size, w:size, h:size, v:2+Math.random()*2});
}
function spawnOrb(){
  const size = 15;
  orbs.push({x:Math.random()* (canvas.width-size), y:-size, w:size, h:size, v:1.5});
}

function rectsCollide(a,b){
  return a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y;
}

function update(){
  // move ship
  if(keys.ArrowLeft) ship.x -= ship.speed;
  if(keys.ArrowRight) ship.x += ship.speed;
  if(keys.ArrowUp) ship.y -= ship.speed;
  if(keys.ArrowDown) ship.y += ship.speed;
  ship.x = Math.max(0, Math.min(canvas.width-ship.w, ship.x));
  ship.y = Math.max(0, Math.min(canvas.height-ship.h, ship.y));

  // spawn
  const now = performance.now();
  if(now-lastAst>800) {spawnAsteroid(); lastAst=now;}
  if(now-lastOrb>1500) {spawnOrb(); lastOrb=now;}

  // update asteroids
  asteroids.forEach(a=>a.y+=a.v);
  asteroids = asteroids.filter(a=> a.y<canvas.height);
  // update orbs
  orbs.forEach(o=>o.y+=o.v);
  orbs = orbs.filter(o=> o.y<canvas.height);

  // collisions
  asteroids = asteroids.filter(a=>{
    if(rectsCollide(ship,a)) {ship.health--; return false;}
    return true;
  });
  orbs = orbs.filter(o=>{
    if(rectsCollide(ship,o)) {score+=10; return false;}
    return true;
  });
}

function draw(){
  ctx.fillStyle='black';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // stars background
  ctx.fillStyle='white';
  for(let i=0;i<100;i++){
    const sx=Math.random()*canvas.width, sy=Math.random()*canvas.height;
    ctx.fillRect(sx,sy,1,1);
  }
  // ship
  ctx.fillStyle='cyan';
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
  // asteroids
  ctx.fillStyle='gray';
  asteroids.forEach(a=>ctx.fillRect(a.x,a.y,a.w,a.h));
  // orbs
  ctx.fillStyle='yellow';
  orbs.forEach(o=>ctx.fillRect(o.x,o.y,o.w,o.h));
  // UI
  ctx.fillStyle='white';
  ctx.font='16px sans-serif';
  ctx.fillText('Score: '+score,10,20);
  ctx.fillText('Health: '+ship.health,10,40);
}

function loop(){
  if(ship.health<=0){
    ctx.fillStyle='red';
    ctx.font='48px sans-serif';
    ctx.fillText('Game Over',canvas.width/2-120,canvas.height/2);
    return;
  }
  update();
  draw();
  requestAnimationFrame(loop);
}
loop();
